SIGNAL SAL: STD_LOGIC_VECTOR(198 DOWNTO 0);
SIGNAL PIX: STD_LOGIC;
SIGNAL COLOR: INTEGER RANGE 0 TO 2;
BEGIN

	PROCESS(CLK, RST2, HPOS, VPOS, VIDEO) -- PROCESO PARA COLOREAR LOS PIXELES
	BEGIN
		IF RST2 = '1' THEN
			COLOR <= 2;
		ELSIF FALLING_EDGE(CLK) THEN
			IF VIDEO = '1' THEN
				IF (HPOS >= 0 AND HPOS <= 198) AND (VPOS >= 0 AND VPOS <= 199) THEN
					SAL <= ROM(VPOS);
					PIX <= SAL(HPOS);
					IF PIX = '0' THEN
						COLOR <= 0;
					ELSE
						COLOR <= 1;
					END IF;
				ELSE
						COLOR <= 2;
				END IF;
			END IF;
		END IF;
	END PROCESS;
	
					
	WITH COLOR SELECT
		RGB <= "001" WHEN 0,
		       "011" WHEN 1,
				 "000" WHEN OTHERS;		
	
END BEAS;
